ld c,(hl)        inc l        ld b,(hl) ;bc=dist        ld d,b        ld e,c        inc l        dup 3;4        srl d        rr e        edup        ld a,d        or a        jr z,$+4         ld e,255        or e        jr nz,$+3         inc e        ld d,t1x/256        ld a,(de) ;width*k (for typical sprite width)        ld e,a        ld a,(hl) ;xscr (центр = 0x40)        sub e        jr nc,$+3         xor a ;a=sprite left margin        cp SCRWIDPIX/2;0x40;TODO связано с scrwid/2        jr nc,fire_miss        ld a,(hl) ;xscr        add a,e        jr nc,$+3         sbc a,a ;a=sprite right margin        cp SCRWIDPIX/2;0x40;TODO связано с scrwid/2        jr c,fire_miss        push hl;не убивать, если стена впереди закрывает монстра (т.е. стена ближе);bc=dist;приводим к 128..255        LD DE,#000        INC B        DEC B        LD A,C        jr Z,fire_MOTOLOGRLQ       DUP 5;6        INC D        SRL B        RRA         jr Z,fire_MOTOLOGRLE       EDUP fire_MOTOLOGRLQ ;fire_MOTOLOGRLE ;        LD C,A ;128..255 ;D=0..5        LD B,tlogd/256        LD A,(BC) ;log(dist) = 128..255 for arg>=128       if atm==0       SUB 16;64                 ;0..127 for arg=64..127 ;???       endif        LD C,A                ;0 for arg<64        LD B,tlogd2sca/256         SRA D         RR E ;DE=+0,+#80,..+#300        ex de,hl        ADD HL,BC        LD a,(HL) ;scale#        pop hlfire_walldist=$+1        cp 0        jr c,fire_miss        push hl        ;найти этого монстра в таблице монстров        inc l        ld l,(hl) ;monster index        ld h,0        add hl,hl        add hl,hl        add hl,hl ;*8        ld bc,MONSTRS+1 ;Xx,Yy,TYPEphase,TIMEenergy        add hl,bc        ld (hl),0xc0 ;impossible X        ld a,0;5        call sfxplay        pop hl        jr fire_missqfire_miss        push hl        ld a,1        call sfxplay        pop hlfire_missq       if CURSPRITES_RECSZ == 5       inc l    